{"command":"cd /workspace && rm -rf scratch && mkdir -p scratch && cat > scratch/ft.py << 'EOF'
import subprocess, json, sys

def ft(tool, args):
    r = subprocess.run(['ft2','call',tool,json.dumps(args)], capture_output=True, text=True)
    # the tool returns JSON wrapper with content text; print and return
    try:
        j = json.loads(r.stdout)
        txt = j['content'][0]['text']
        try:
            inner = json.loads(txt)
        except Exception:
            inner = txt
        return inner
    except Exception:
        return r.stdout[:500]

if __name__ == '__main__':
    out = ft(sys.argv[1], json.loads(sys.argv[2]))
    print(out)
EOF
echo ok"}

