def N(name):
    # name like C4, A#4, E5
    import re
    m = re.match(r'^([A-G][#]?s?|B[#]?s?)(\d)$', name)
    # simpler: split accidental
    m = re.match(r'^([A-G])(#?)(s?)(\d)$', name)
    if not m:
        raise ValueError(name)
    root, sharp, _, octave = m.groups()
    semis = SEMI[root + ('#' if sharp else '')]
    if sharp == 's':
        semis = SEMI[root + '#'] # treat 's' as accidental too
    return 1 + 12*int(octave) + semis
